    AND lat.user_id = #{userId}

        AND la.level = #{level}


        AND la.task_id = #{taskId}


ORDER BY la.create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM log_alarm


        AND level = #{level}


        AND task_id = #{taskId}

SELECT COUNT(*)
FROM log_alarm la
JOIN log_analysis_task lat ON lat.task_id = la.task_id

    AND lat.user_id = #{userId}

        AND la.level = #{level}


        AND la.task_id = #{taskId}

SELECT DATE(create_time) AS date, COUNT(*) AS count FROM log_alarm WHERE create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
AND level = #{level}
AND task_id = #{taskId}
GROUP BY DATE(create_time) ORDER BY date

SELECT DATE(la.create_time) AS date, COUNT(*) AS count FROM log_alarm la JOIN log_analysis_task lat ON lat.task_id = la.task_id WHERE lat.user_id = #{userId} AND la.create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
AND la.level = #{level}
AND la.task_id = #{taskId}
GROUP BY DATE(la.create_time) ORDER BY date

SELECT level, COUNT(*) AS count FROM log_alarm WHERE create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
AND level = #{level}
AND task_id = #{taskId}
GROUP BY level ORDER BY count DESC

SELECT la.level AS level, COUNT(*) AS count FROM log_alarm la JOIN log_analysis_task lat ON lat.task_id = la.task_id WHERE lat.user_id = #{userId} AND la.create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
AND la.level = #{level}
AND la.task_id = #{taskId}
GROUP BY la.level ORDER BY count DESC

SELECT LEFT(root_cause, 20) AS root_cause, COUNT(*) AS count FROM log_alarm WHERE create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY) AND root_cause IS NOT NULL
AND level = #{level}
AND task_id = #{taskId}
GROUP BY LEFT(root_cause, 20) ORDER BY count DESC LIMIT 10

SELECT LEFT(la.root_cause, 20) AS root_cause, COUNT(*) AS count FROM log_alarm la JOIN log_analysis_task lat ON lat.task_id = la.task_id WHERE lat.user_id = #{userId} AND la.create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY) AND la.root_cause IS NOT NULL
AND la.level = #{level}
AND la.task_id = #{taskId}
GROUP BY LEFT(la.root_cause, 20) ORDER BY count DESC LIMIT 10

SELECT COUNT(*) AS total_alarms, SUM(CASE WHEN push_status IN ('SUCCESS', 'RECORDED') THEN 1 ELSE 0 END) AS success_alarms, SUM(CASE WHEN push_status = 'FAILED' THEN 1 ELSE 0 END) AS failed_alarms FROM log_alarm WHERE create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
AND level = #{level}
AND task_id = #{taskId}

SELECT
    COUNT(*) AS total_alarms,
    SUM(CASE WHEN la.push_status IN ('SUCCESS', 'RECORDED') THEN 1 ELSE 0 END) AS success_alarms,
    SUM(CASE WHEN la.push_status = 'FAILED' THEN 1 ELSE 0 END) AS failed_alarms
FROM log_alarm la
JOIN log_analysis_task lat ON lat.task_id = la.task_id
WHERE lat.user_id = #{userId}
  AND la.create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)

    AND la.level = #{level}


    AND la.task_id = #{taskId}
